import React, { useState } from 'react';
import { MessageSquare, X, Send } from 'lucide-react';
import { IMAGES } from '../constants';

export const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [message, setMessage] = useState('');
  const [chatLog, setChatLog] = useState<{ role: 'user' | 'bot', text: string }[]>([
    { role: 'bot', text: 'Welcome to Cornelius TEC Support. How can we innovate with you today?' }
  ]);

  const handleSend = () => {
    if (!message.trim()) return;
    setChatLog([...chatLog, { role: 'user', text: message }]);
    setMessage('');

    // Simulate bot response
    setTimeout(() => {
      setChatLog(prev => [...prev, { role: 'bot', text: 'Thank you for your inquiry. A specialized tech advisor will be with you shortly!' }]);
    }, 1000);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60]">
      {!isOpen ? (
        <button
          onClick={() => setIsOpen(true)}
          className="bg-gradient-to-r from-neon-blue to-neon-purple p-4 rounded-full shadow-2xl hover:scale-110 transition-transform neon-glow-blue animate-bounce"
        >
          <MessageSquare className="text-white w-6 h-6" />
        </button>
      ) : (
        <div className="w-80 h-96 glassmorphism rounded-2xl flex flex-col overflow-hidden animate-slide-up neon-glow-purple">
          <div className="bg-gradient-to-r from-neon-blue/20 to-neon-purple/20 p-4 flex justify-between items-center border-b border-white/10">
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse" />
              <span className="font-heading text-xs tracking-widest uppercase">Live Support</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-white">
              <X size={20} />
            </button>
          </div>

          <div className="flex-grow overflow-y-auto p-4 space-y-3 font-body text-sm">
            {chatLog.map((chat, idx) => (
              <div key={idx} className={`flex ${chat.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] px-3 py-2 rounded-xl ${
                  chat.role === 'user' 
                    ? 'bg-neon-blue/20 text-blue-100 rounded-br-none' 
                    : 'bg-white/5 text-gray-300 rounded-bl-none'
                }`}>
                  {chat.text}
                </div>
              </div>
            ))}
          </div>

          <div className="p-4 border-t border-white/10 flex items-center space-x-2">
            <input
              type="text"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Type your message..."
              className="flex-grow bg-white/5 border border-white/10 rounded-full px-4 py-2 text-xs focus:outline-none focus:border-neon-blue"
            />
            <button onClick={handleSend} className="text-neon-blue hover:scale-110 transition-transform">
              <Send size={18} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

