import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Volume2, VolumeX, Sparkles } from 'lucide-react';
import { GoogleGenAI, Modality } from '@google/genai';
import { IMAGES } from '../constants';

// Helper for base64 decoding to audio buffer
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(false);
  const [isThinking, setIsThinking] = useState(false);
  const [message, setMessage] = useState('');
  const [chatLog, setChatLog] = useState<{ role: 'user' | 'bot', text: string }[]>([
    { role: 'bot', text: "I am Corneila, your AI Concierge. How can Cornelius TEC help you defy gravity today?" }
  ]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [chatLog, isThinking]);

  const speakText = async (text: string) => {
    if (!isVoiceEnabled) return;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Say in a professional, warm, and futuristic voice: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' }, // Warm, high-quality voice
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("Speech synthesis failed", error);
    }
  };

  const handleSend = async () => {
    if (!message.trim() || isThinking) return;

    const userMsg = message.trim();
    setChatLog(prev => [...prev, { role: 'user', text: userMsg }]);
    setMessage('');
    setIsThinking(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are Corneila, the advanced AI Concierge for Cornelius TEC. 
          Cornelius TEC specializes in website building, app creation, AI systems, and social media management. 
          Tone: Professional, futuristic, and proudly reflects African innovation—bold, helpful, and unforgettable. 
          Tagline: "Cornelius TEC — Innovation That Defies Gravity."
          Locations: Rwanda / Liberia. 
          Contact: +250796569416.
          Respond concisely and helpfully. If the user wants to book, direct them to the Appointment page. If they want to buy assets, direct them to the Marketplace.`,
        },
      });

      const result = await chat.sendMessage({ message: userMsg });
      const botResponse = result.text || "Apologies, my neural link is flickering. Please try again.";

      setChatLog(prev => [...prev, { role: 'bot', text: botResponse }]);
      setIsThinking(false);

      if (isVoiceEnabled) {
        await speakText(botResponse);
      }
    } catch (error) {
      console.error("AI Chat failed", error);
      setChatLog(prev => [...prev, { role: 'bot', text: "Systems are temporarily offline. Please contact us at +250796569416." }]);
      setIsThinking(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60]">
      {!isOpen ? (
        <button
          onClick={() => setIsOpen(true)}
          className="bg-gradient-to-r from-neon-blue to-neon-purple p-4 rounded-full shadow-2xl hover:scale-110 transition-transform neon-glow-blue animate-bounce flex items-center justify-center"
        >
          <Sparkles className="text-white w-6 h-6" />
        </button>
      ) : (
        <div className="w-80 md:w-96 h-[500px] glassmorphism rounded-3xl flex flex-col overflow-hidden animate-slide-up neon-glow-purple border border-white/20">
