      setIsThinking(false);

      if (isVoiceEnabled) {
        await speakText(botResponse);
      }
    } catch (error) {
      console.error("AI Communication Link Error:", error);
      setChatLog(prev => [...prev, { role: 'bot', text: "Neural systems recalibrating. Contact +250796569416 for human assistance." }]);
      setIsThinking(false);
    }
  };

  const toggleVoice = async () => {
    if (isVoiceEnabled) {
      stopSpeaking();
      setIsVoiceEnabled(false);
    } else {
      const ctx = await initAudio();
      setIsVoiceEnabled(true);
      // Brief feedback tone to confirm audio unlock
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0.01, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.5);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.5);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60]">
