import React, { useState } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Sparkles, Wand2, Download, RefreshCcw, Image as ImageIcon, Loader2 } from 'lucide-react';

export const DesignLab: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { text: `A futuristic, high-tech, professional brand asset or architectural concept in an Afro-futuristic style: ${prompt}. Cinematic lighting, 8k resolution, elegant textures.` }
          ]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9"
          }
        }
      });

      let foundImage = false;
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          const imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          setGeneratedImage(imageUrl);
          foundImage = true;
          break;
        }
      }

      if (!foundImage) {
        throw new Error("No image data received from the neural link.");
      }
    } catch (err: any) {
      console.error(err);
      setError("Neural link interrupted. Please recalibrate your prompt.");
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadImage = () => {
    if (!generatedImage) return;
    const link = document.createElement('a');
    link.href = generatedImage;
    link.download = `cornelius-tec-vision-${Date.now()}.png`;
    link.click();
  };

  return (
    <div className="pt-24 pb-32 max-w-7xl mx-auto px-4">
      <div className="flex flex-col lg:flex-row gap-16 items-start">
        {/* Left Control Panel */}
        <div className="w-full lg:w-1/3 sticky top-32">
          <div className="inline-flex items-center space-x-2 mb-6 px-4 py-1 glassmorphism border border-neon-blue/30 rounded-full">
            <Sparkles size={14} className="text-neon-blue animate-pulse" />
            <span className="text-neon-blue font-heading text-[10px] tracking-[0.3em] uppercase">Neural Forge v2.5</span>
          </div>

          <h1 className="font-heading text-4xl md:text-5xl mb-6 tracking-tight">
            THE <span className="text-neon-purple">DESIGN</span> LAB
          </h1>
          <p className="text-gray-400 font-subheading mb-10 leading-relaxed">
            Manifest your digital infrastructure visually. Our custom-trained AI translates your ambitions into high-fidelity architectural concepts.
          </p>

          <div className="glassmorphism p-8 rounded-[2.5rem] border border-white/5 shadow-2xl african-pattern">
            <label className="block text-[10px] uppercase tracking-[0.4em] text-gray-500 mb-4 font-heading">Concept Parameters</label>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="e.g. A floating server hub in the shape of an Adinkra symbol, neon cyan accents, dusk sky..."
              className="w-full bg-black/40 border border-white/10 rounded-2xl p-6 text-sm font-body text-white focus:outline-none focus:border-neon-blue transition-all min-h-[150px] resize-none mb-6"
            />

            <button
              onClick={handleGenerate}
              disabled={isGenerating || !prompt.trim()}
              className="w-full bg-gradient-to-r from-neon-blue to-neon-purple text-dark-bg font-heading py-5 rounded-2xl flex items-center justify-center space-x-3 hover:scale-[1.02] active:scale-95 transition-all shadow-2xl disabled:opacity-20"
            >
              {isGenerating ? (
                <Loader2 className="animate-spin" size={20} />
              ) : (
                <>
                  <Wand2 size={20} />
                  <span>INITIALIZE VISION</span>
                </>
              )}
            </button>

            {error && (
              <p className="mt-4 text-xs text-red-400 font-accent text-center italic">{error}</p>
            )}
          </div>
        </div>

        {/* Right Output Area */}
        <div className="flex-grow w-full">
          <div className="relative aspect-video glassmorphism rounded-[3rem] border border-white/10 overflow-hidden flex items-center justify-center group shadow-2xl">
            {generatedImage ? (
              <>
                <img src={generatedImage} alt="Neural Vision" className="w-full h-full object-cover animate-fade-in" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-6">
                  <button 
                    onClick={downloadImage}
                    className="p-5 bg-white text-dark-bg rounded-2xl hover:bg-neon-blue transition-colors shadow-2xl flex items-center space-x-2"
                  >
                    <Download size={20} />
                    <span className="font-heading text-xs tracking-widest">ARCHIVE</span>
                  </button>
                  <button 
                    onClick={handleGenerate}
                    className="p-5 bg-white/10 text-white backdrop-blur-md rounded-2xl border border-white/20 hover:bg-white/20 transition-colors flex items-center space-x-2"
                  >
                    <RefreshCcw size={20} />
                    <span className="font-heading text-xs tracking-widest">REGENERATE</span>
                  </button>
                </div>
              </>
            ) : (
              <div className="text-center p-12">
                <div className="w-24 h-24 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-8 border border-white/10">
                  <ImageIcon size={40} className="text-gray-600 animate-pulse" />
                </div>
                <h3 className="font-heading text-xl text-gray-500 mb-2 uppercase tracking-widest">Visual Output Pending</h3>
                <p className="text-gray-600 font-subheading text-sm max-w-xs mx-auto">
                  Submit a concept to engage the neural drafting system.
                </p>
              </div>
            )}

            {/* Scanning Effect Overlay */}
            {isGenerating && (
              <div className="absolute inset-0 z-20 pointer-events-none overflow-hidden">
                <div className="w-full h-1 bg-neon-blue/50 shadow-[0_0_20px_#00CFFF] absolute top-0 animate-[scan_2s_linear_infinite]" />
                <div className="absolute inset-0 bg-neon-blue/5 animate-pulse" />
              </div>
            )}
          </div>

          {/* Prompt Suggestions */}
          <div className="mt-12">
            <h4 className="font-heading text-xs text-gray-500 uppercase tracking-[0.4em] mb-6">Trending Neural Templates</h4>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {[
                "Cyber-Kente Dashboard UI",
                "Obsidian Solar Hub Rwanda",
                "Holographic App Interface",
                "Digital Nomad Oasis Liberia"
              ].map(suggest => (
                <button
                  key={suggest}
                  onClick={() => setPrompt(suggest)}
                  className="p-4 glassmorphism border border-white/5 rounded-2xl text-[10px] font-subheading text-gray-400 hover:text-neon-blue hover:border-neon-blue/30 transition-all text-left uppercase tracking-widest"
                >
                  {suggest}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0% { top: -5%; }
          100% { top: 105%; }
        }
      `}</style>
    </div>
  );
};

