import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Volume2, VolumeX, Sparkles, Headphones, Zap, Loader2, Database } from 'lucide-react';
import { GoogleGenAI, Modality } from '@google/genai';
import { IMAGES } from '../constants';

// Standard base64 to Uint8Array
function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper for raw PCM decoding to audio buffer
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const buffer = data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength);
  const dataInt16 = new Int16Array(buffer);
  const frameCount = dataInt16.length / numChannels;
  const audioBuffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = audioBuffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return audioBuffer;
}

// Aligning with the provided schema:
// { _id: ObjectId, userId: ObjectId, message: String, timestamp: Date }
interface ChatMessage {
  _id: string;
  userId: string;
  message: string;
  timestamp: Date;
}

export const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(false);
  const [isThinking, setIsThinking] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [message, setMessage] = useState('');

  // Initial message following the schema
  const [chatLog, setChatLog] = useState<ChatMessage[]>([
    { 
      _id: 'msg_' + Math.random().toString(16).slice(2, 10),
      userId: 'corneila-id', 
      message: "Greetings. I am Corneila, your AI Concierge at Cornelius TEC. How shall we innovate together today?",
      timestamp: new Date()
    }
  ]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [chatLog, isThinking, isSpeaking]);

  const initAudio = async () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }
    return audioContextRef.current;
  };

  const stopSpeaking = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {}
      currentSourceRef.current = null;
    }
    setIsSpeaking(false);
  };

  const speakText = async (text: string) => {
    if (!isVoiceEnabled) return;

    try {
      stopSpeaking();
      setIsSpeaking(true);

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = await initAudio();
        const rawData = decodeBase64(base64Audio);
        const audioBuffer = await decodeAudioData(rawData, ctx, 24000, 1);

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsSpeaking(false);
        currentSourceRef.current = source;
        source.start(0);
      } else {
        setIsSpeaking(false);
      }
    } catch (error) {
      console.error("Neural Voice Generation Error:", error);
      setIsSpeaking(false);
    }
  };

  const handleSend = async () => {
    if (!message.trim() || isThinking) return;

    await initAudio();

    const userMsgText = message.trim();
    const userMessageObj: ChatMessage = {
      _id: 'msg_' + Math.random().toString(16).slice(2, 14),
      userId: 'mock-user-id-777', // User identity mapping
      message: userMsgText,
      timestamp: new Date()
    };

    setChatLog(prev => [...prev, userMessageObj]);
    console.log("Saving User Message to Matrix:", userMessageObj);

    setMessage('');
    setIsThinking(true);
    stopSpeaking();

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are Corneila, the advanced AI Concierge for Cornelius TEC. 
          Company: Cornelius TEC. 
          Mission: "Innovation That Defies Gravity." 
          Concise responses only.`,
        },
      });

      const result = await chat.sendMessage({ message: userMsgText });
      const botResponseText = result.text || "Transmission error. Please re-initiate link.";

      const botMessageObj: ChatMessage = {
        _id: 'msg_' + Math.random().toString(16).slice(2, 14),
        userId: 'corneila-id', // Bot identity mapping
        message: botResponseText,
        timestamp: new Date()
      };

      setChatLog(prev => [...prev, botMessageObj]);
      console.log("Saving Bot Message to Matrix:", botMessageObj);

      setIsThinking(false);

      if (isVoiceEnabled) {
        await speakText(botResponseText);
      }
    } catch (error) {
      console.error("AI Communication Link Error:", error);
      const errorMsg: ChatMessage = {
        _id: 'err_' + Date.now(),
        userId: 'corneila-id',
        message: "Neural systems recalibrating. Contact +250796569416 for human assistance.",
        timestamp: new Date()
      };
      setChatLog(prev => [...prev, errorMsg]);
      setIsThinking(false);
    }
  };

  const toggleVoice = async () => {
    if (isVoiceEnabled) {
      stopSpeaking();
      setIsVoiceEnabled(false);
    } else {
      const ctx = await initAudio();
      setIsVoiceEnabled(true);
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0.01, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.5);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.5);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60]">
      {!isOpen ? (
        <button
          onClick={() => setIsOpen(true)}
          className="bg-gradient-to-r from-neon-blue to-neon-purple p-4 rounded-full shadow-2xl hover:scale-110 transition-transform neon-glow-blue animate-bounce flex items-center justify-center group"
        >
          <MessageSquare className="text-white w-6 h-6" />
        </button>
      ) : (
        <div className="w-[320px] md:w-[400px] h-[600px] glassmorphism rounded-[2.5rem] flex flex-col overflow-hidden animate-slide-up shadow-2xl border border-white/10">
          {/* Header */}
          <div className="bg-gradient-to-r from-neon-blue/20 to-neon-purple/20 p-5 flex justify-between items-center border-b border-white/10 backdrop-blur-xl">
            <div className="flex items-center space-x-3">
              <div className="relative">
                <div className={`w-12 h-12 rounded-full bg-gradient-to-tr from-neon-blue to-neon-purple p-[2px] transition-all duration-500 ${isSpeaking ? 'scale-110 shadow-[0_0_20px_rgba(0,207,255,0.5)]' : ''}`}>
                  <div className="w-full h-full rounded-full overflow-hidden bg-dark-bg">
                    <img src={IMAGES.profile} className={`w-full h-full object-cover ${isSpeaking ? 'opacity-100 scale-105' : 'opacity-70'} transition-all`} alt="Corneila" />
                  </div>
                </div>
                {isSpeaking && (
                   <>
                    <div className="absolute -inset-1 border-2 border-neon-blue rounded-full animate-ping opacity-30" />
                    <div className="absolute -inset-2 border border-neon-purple rounded-full animate-pulse opacity-20" />
                   </>
                )}
              </div>
              <div>
                <div className="flex items-center space-x-2">
                  <span className="font-heading text-[10px] tracking-widest uppercase block text-neon-blue">Neural Node</span>
                  <div className="flex items-center space-x-1 text-[8px] text-green-400 font-accent animate-pulse">
                    <Database size={8} />
                    <span>SYNC ACTIVE</span>
                  </div>
                </div>
                <span className="text-sm font-heading tracking-tight text-white block">CORNEILA AI</span>
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={toggleVoice} 
                className={`p-2.5 rounded-xl transition-all ${isVoiceEnabled ? 'bg-neon-blue text-dark-bg shadow-[0_0_20px_rgba(0,207,255,0.4)]' : 'bg-white/5 text-gray-500 hover:text-white'}`}
                title={isVoiceEnabled ? "Mute Voice" : "Enable Voice"}
              >
                {isVoiceEnabled ? <Volume2 size={18} /> : <VolumeX size={18} />}
              </button>
              <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-white p-2.5 hover:bg-white/5 rounded-xl transition-colors">
                <X size={20} />
              </button>
            </div>
          </div>

          {/* Chat Body */}
          <div ref={scrollRef} className="flex-grow overflow-y-auto p-5 space-y-6 font-body text-sm custom-scrollbar bg-black/10">
            {chatLog.map((chat) => (
              <div key={chat._id} className={`flex flex-col ${chat.userId === 'corneila-id' ? 'items-start' : 'items-end'}`}>
                <div className={`max-w-[85%] px-5 py-4 rounded-[1.8rem] shadow-lg transition-all ${
                  chat.userId === 'corneila-id' 
                    ? 'bg-white/5 text-gray-200 border border-white/10 rounded-tl-none backdrop-blur-md' 
                    : 'bg-gradient-to-br from-neon-blue to-neon-purple text-white rounded-tr-none border border-white/10'
                }`}>
                  {chat.message}
                </div>
                <span className="mt-1.5 px-2 text-[8px] text-gray-600 font-accent uppercase tracking-widest">
                  {chat.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} • {chat.userId.slice(0, 8)}
                </span>
              </div>
            ))}

            {isThinking && (
              <div className="flex justify-start">
                <div className="bg-white/5 border border-white/10 px-5 py-4 rounded-2xl rounded-tl-none flex space-x-2 items-center">
                  <Loader2 className="w-3 h-3 text-neon-blue animate-spin" />
                  <span className="text-[9px] uppercase tracking-[0.2em] text-gray-500 font-heading">Processing</span>
                </div>
              </div>
            )}

            {isSpeaking && (
              <div className="flex justify-center py-2">
                <div className="flex items-center space-x-3 bg-neon-blue/10 border border-neon-blue/30 px-6 py-2 rounded-full backdrop-blur-md">
                  <Zap size={12} className="text-neon-blue animate-pulse" />
                  <div className="flex items-end space-x-1 h-4">
                    <div className="w-1 bg-neon-blue animate-[voice_0.5s_ease-in-out_infinite]"></div>
                    <div className="w-1 bg-neon-purple animate-[voice_0.7s_ease-in-out_infinite_0.1s]"></div>
                    <div className="w-1 bg-neon-blue animate-[voice_0.6s_ease-in-out_infinite_0.2s]"></div>
                    <div className="w-1 bg-neon-purple animate-[voice_0.8s_ease-in-out_infinite_0.3s]"></div>
                    <div className="w-1 bg-neon-blue animate-[voice_0.5s_ease-in-out_infinite_0.4s]"></div>
                  </div>
                  <span className="text-[9px] uppercase tracking-widest text-neon-blue font-heading">Audio Signal</span>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-5 border-t border-white/10 bg-black/40 backdrop-blur-md">
            <div className="relative flex items-center">
              <input
                type="text"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Type your query..."
                disabled={isThinking}
                className="w-full bg-white/5 border border-white/10 rounded-2xl pl-5 pr-14 py-4 text-xs focus:outline-none focus:border-neon-blue transition-all disabled:opacity-50 text-white placeholder:text-gray-600 font-subheading"
              />
              <button 
                onClick={handleSend} 
                disabled={isThinking || !message.trim()}
                className="absolute right-2 bg-gradient-to-r from-neon-blue to-neon-purple text-white p-3 rounded-xl hover:scale-105 active:scale-95 transition-all disabled:opacity-20 shadow-lg"
              >
                <Send size={16} />
              </button>
            </div>
            <div className="flex justify-center mt-3">
               <p className="text-[8px] text-gray-700 uppercase tracking-[0.3em] font-accent">
                Syncing with Cornelius Matrix
              </p>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes voice {
          0%, 100% { height: 4px; opacity: 0.5; }
          50% { height: 16px; opacity: 1; }
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: rgba(0, 207, 255, 0.2);
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

