import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Sparkles, Wand2, Download, RefreshCcw, Image as ImageIcon, Loader2, History, Terminal as TerminalIcon, Trash2 } from 'lucide-react';

interface VisionArchive {
  id: string;
  prompt: string;
  url: string;
  timestamp: Date;
}

export const DesignLab: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [archive, setArchive] = useState<VisionArchive[]>([]);
  const [logs, setLogs] = useState<string[]>(["Neural Forge initialized.", "Standby for transmission..."]);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 10));
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    addLog(`Initiating sequence for: ${prompt.slice(0, 20)}...`);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [
            { text: `A futuristic, high-tech, professional brand asset or architectural concept in an Afro-futuristic style: ${prompt}. Cinematic lighting, 8k resolution, elegant textures.` }
          ]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9"
          }
        }
      });

      let foundImage = false;
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          const imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          setGeneratedImage(imageUrl);

          const newEntry: VisionArchive = {
            id: Date.now().toString(),
            prompt: prompt,
            url: imageUrl,
            timestamp: new Date()
          };
          setArchive(prev => [newEntry, ...prev]);
          addLog("Neural mapping complete. Vision saved to archive.");
          foundImage = true;
          break;
        }
      }

      if (!foundImage) {
        throw new Error("No image data received from the neural link.");
      }
    } catch (err: any) {
      console.error(err);
      setError("Neural link interrupted. Please recalibrate your prompt.");
      addLog("Critical Error: Transmission failed.");
    } finally {
      setIsGenerating(false);
    }
  };

  const clearArchive = () => setArchive([]);

  return (
    <div className="pt-24 pb-32 max-w-7xl mx-auto px-4">
      <div className="flex flex-col lg:flex-row gap-16 items-start">
        {/* Left Control Panel */}
        <div className="w-full lg:w-1/3 sticky top-32">
          <div className="inline-flex items-center space-x-2 mb-6 px-4 py-1 glassmorphism border border-neon-blue/30 rounded-full">
            <Sparkles size={14} className="text-neon-blue animate-pulse" />
            <span className="text-neon-blue font-heading text-[10px] tracking-[0.3em] uppercase">Neural Forge v2.5</span>
          </div>

          <h1 className="font-heading text-4xl md:text-5xl mb-6 tracking-tight">
            THE <span className="text-neon-purple">DESIGN</span> LAB
          </h1>

          <div className="glassmorphism p-8 rounded-[2.5rem] border border-white/5 shadow-2xl african-pattern mb-8">
            <label className="block text-[10px] uppercase tracking-[0.4em] text-gray-500 mb-4 font-heading">Concept Parameters</label>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="e.g. A floating server hub in the shape of an Adinkra symbol..."
              className="w-full bg-black/40 border border-white/10 rounded-2xl p-6 text-sm font-body text-white focus:outline-none focus:border-neon-blue transition-all min-h-[120px] resize-none mb-6"
            />

            <button
              onClick={handleGenerate}
              disabled={isGenerating || !prompt.trim()}
              className="w-full bg-gradient-to-r from-neon-blue to-neon-purple text-dark-bg font-heading py-5 rounded-2xl flex items-center justify-center space-x-3 hover:scale-[1.02] active:scale-95 transition-all shadow-2xl disabled:opacity-20"
            >
              {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <><Wand2 size={20} /><span>INITIALIZE VISION</span></>}
            </button>
          </div>

          {/* Terminal Log */}
          <div className="glassmorphism p-6 rounded-[2rem] border border-white/5 bg-black/40 font-mono">
             <div className="flex items-center space-x-2 mb-4">
                <TerminalIcon size={12} className="text-neon-blue" />
                <span className="text-[9px] uppercase tracking-widest text-gray-500">Neural Log</span>
             </div>
             <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                {logs.map((log, i) => (
                  <div key={i} className="text-[10px] text-gray-400">
                    <span className="text-neon-blue mr-2">&gt;</span>{log}
                  </div>
                ))}
             </div>
          </div>
        </div>

        {/* Right Output Area */}
        <div className="flex-grow w-full space-y-12">
          <div className="relative aspect-video glassmorphism rounded-[3rem] border border-white/10 overflow-hidden flex items-center justify-center group shadow-2xl">
            {generatedImage ? (
              <img src={generatedImage} alt="Neural Vision" className="w-full h-full object-cover animate-fade-in" />
            ) : (
              <div className="text-center p-12 opacity-30">
                <ImageIcon size={48} className="mx-auto mb-4 animate-pulse" />
                <p className="font-heading text-xs tracking-widest uppercase">Output Pending</p>
              </div>
            )}

            {isGenerating && (
              <div className="absolute inset-0 z-20 pointer-events-none overflow-hidden">
                <div className="w-full h-1 bg-neon-blue/50 shadow-[0_0_20px_#00CFFF] absolute top-0 animate-[scan_2s_linear_infinite]" />
                <div className="absolute inset-0 bg-neon-blue/5 animate-pulse" />
              </div>
            )}
          </div>

          {/* Archive Section */}
          <div>
             <div className="flex justify-between items-center mb-8">
                <div className="flex items-center space-x-3">
                   <History size={18} className="text-neon-purple" />
                   <h3 className="font-heading text-xl uppercase tracking-widest">Neural Archive</h3>
                </div>
                {archive.length > 0 && (
                   <button onClick={clearArchive} className="text-gray-600 hover:text-red-400 transition-colors">
                      <Trash2 size={16} />
                   </button>
                )}
             </div>

             <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                {archive.map((entry) => (
                  <div key={entry.id} className="group relative aspect-video glassmorphism rounded-2xl overflow-hidden border border-white/5 cursor-pointer hover:border-neon-blue/30 transition-all">
                     <img src={entry.url} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-all" />
                     <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all p-4 flex flex-col justify-end">
                        <p className="text-[8px] text-white font-body truncate uppercase tracking-widest">{entry.prompt}</p>
                        <button onClick={() => setGeneratedImage(entry.url)} className="text-neon-blue text-[8px] font-heading mt-1">RECALL</button>
                     </div>
                  </div>
                ))}
                {archive.length === 0 && (
                  <div className="col-span-full py-12 text-center border border-dashed border-white/5 rounded-3xl opacity-20">
                     <p className="text-xs uppercase tracking-[0.3em]">Archive Empty</p>
                  </div>
                )}
             </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scan { 0% { top: -5%; } 100% { top: 105%; } }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0, 207, 255, 0.2); }
      `}</style>
    </div>
  );
};

