import axios from 'axios';
import { io } from "socket.io-client";

const API = axios.create({
  baseURL: "http://localhost:5000", // Default backend endpoint
});

// Real-time communication node
export const socket = io("http://localhost:5000", {
  autoConnect: false, // Don't connect until needed
});

// Add token to requests if logged in
API.interceptors.request.use((req) => {
  const token = localStorage.getItem("token");
  if (token) {
    req.headers.Authorization = `Bearer ${token}`;
    // Optionally pass token to socket auth
    if (socket.auth) {
      (socket.auth as any).token = token;
    }
  }
  return req;
});

export default API;

// Auth Operations
export const authAPI = {
  signup: (formData: any) => API.post("/auth/signup", formData),
  login: (formData: any) => API.post("/auth/login", formData),
  getProfile: () => API.get("/auth/profile"),
};

// Appointment Operations
export const appointmentAPI = {
  create: (data: any) => API.post("/appointments", data),
  getAll: () => API.get("/appointments"),
  getByUser: (userId: string) => API.get(`/appointments/${userId}`),
  cancel: (id: string) => API.delete(`/appointments/${id}`),
};

// Product Operations
export const productAPI = {
  add: (data: any) => API.post("/products", data),
  getAll: () => API.get("/products"),
  getById: (id: string) => API.get(`/products/${id}`),
};

// Review Operations
export const reviewAPI = {
  submit: (data: any) => API.post("/reviews", data),
  getAll: () => API.get("/reviews"),
  getByProduct: (productId: string) => API.get(`/reviews/${productId}`),
};

// Simplified individual exports for convenience
export const signup = (formData: any) => authAPI.signup(formData);
export const login = (formData: any) => authAPI.login(formData);
export const getProfile = () => authAPI.getProfile();

export const bookAppointment = (data: any) => appointmentAPI.create(data);
export const getAppointments = (userId: string) => appointmentAPI.getByUser(userId);
export const cancelAppointment = (id: string) => appointmentAPI.cancel(id);

export const addProduct = (data: any) => productAPI.add(data);
export const getProducts = () => productAPI.getAll();
export const getProduct = (id: string) => productAPI.getById(id);

export const submitReview = (data: any) => reviewAPI.submit(data);
export const getReviews = () => reviewAPI.getAll();
export const getProductReviews = (productId: string) => reviewAPI.getByProduct(productId);

// Socket Helpers
export const chatSocket = {
  sendMessage: (userId: string, message: string) => {
    socket.emit("chatMessage", { userId, message });
  },
  onMessage: (callback: (msg: any) => void) => {
    socket.on("chatMessage", callback);
  },
  offMessage: () => {
    socket.off("chatMessage");
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Volume2, VolumeX, Sparkles, Headphones, Zap, Loader2, Database, Radio, UserCheck } from 'lucide-react';
import { GoogleGenAI, Modality } from '@google/genai';
import { IMAGES } from '../constants';
import { socket, chatSocket } from '../api';

// Standard base64 to Uint8Array
function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper for raw PCM decoding to audio buffer
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const buffer = data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength);
  const dataInt16 = new Int16Array(buffer);
  const frameCount = dataInt16.length / numChannels;
  const audioBuffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = audioBuffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return audioBuffer;
}

interface ChatMessage {
  _id: string;
  userId: string;
  message: string;
  timestamp: Date;
  isLive?: boolean;
}

export const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(false);
  const [isThinking, setIsThinking] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false);
  const [socketConnected, setSocketConnected] = useState(false);
  const [message, setMessage] = useState('');
  const [userId] = useState(() => 'user_' + Math.random().toString(16).slice(2, 8));

  const [chatLog, setChatLog] = useState<ChatMessage[]>([
    { 
      _id: 'msg_init',
      userId: 'corneila-id', 
      message: "Greetings. I am Corneila, your AI Concierge at Cornelius TEC. How shall we innovate together today?",
      timestamp: new Date()
    }
  ]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [chatLog, isThinking, isSpeaking]);

  // Socket Setup
  useEffect(() => {
    if (isLiveMode) {
      socket.connect();
      socket.on('connect', () => setSocketConnected(true));
      socket.on('disconnect', () => setSocketConnected(false));

      chatSocket.onMessage((msg: any) => {
        const liveMsg: ChatMessage = {
          _id: 'live_' + Date.now(),
          userId: msg.userId === userId ? userId : 'support-agent',
          message: msg.message,
          timestamp: new Date(),
          isLive: true
        };
        // Only add if it's from the other person (ours is added locally for speed)
        if (msg.userId !== userId) {
          setChatLog(prev => [...prev, liveMsg]);
        }
      });
    } else {
      socket.disconnect();
      setSocketConnected(false);
      chatSocket.offMessage();
    }
    return () => {
      socket.off('connect');
      socket.off('disconnect');
      chatSocket.offMessage();
    };
  }, [isLiveMode, userId]);

  const initAudio = async () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      await audioContextRef.current.resume();
    }
    return audioContextRef.current;
  };

  const stopSpeaking = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {}
      currentSourceRef.current = null;
    }
    setIsSpeaking(false);
  };

  const speakText = async (text: string) => {
    if (!isVoiceEnabled) return;
    try {
      stopSpeaking();
      setIsSpeaking(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = await initAudio();
        const rawData = decodeBase64(base64Audio);
        const audioBuffer = await decodeAudioData(rawData, ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsSpeaking(false);
        currentSourceRef.current = source;
        source.start(0);
      } else { setIsSpeaking(false); }
    } catch (error) {
      console.error("Neural Voice Generation Error:", error);
      setIsSpeaking(false);
    }
  };

  const handleSend = async () => {
    if (!message.trim() || isThinking) return;
    const userMsgText = message.trim();
    const userMessageObj: ChatMessage = {
      _id: 'msg_' + Math.random().toString(16).slice(2, 14),
      userId: userId,
      message: userMsgText,
      timestamp: new Date(),
      isLive: isLiveMode
    };

    setChatLog(prev => [...prev, userMessageObj]);
    setMessage('');

    if (isLiveMode) {
      chatSocket.sendMessage(userId, userMsgText);
      return;
    }

    // AI Concierge Logic
    setIsThinking(true);
    stopSpeaking();
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are Corneila, the AI Concierge for Cornelius TEC. Concise responses only. Mission: Innovation That Defies Gravity. Locations: Rwanda, Liberia.`,
        },
      });
      const result = await chat.sendMessage({ message: userMsgText });
      const botResponseText = result.text || "Transmission error.";
      const botMessageObj: ChatMessage = {
        _id: 'msg_' + Math.random().toString(16).slice(2, 14),
        userId: 'corneila-id',
        message: botResponseText,
        timestamp: new Date()
      };
      setChatLog(prev => [...prev, botMessageObj]);
      setIsThinking(false);
      if (isVoiceEnabled) await speakText(botResponseText);
    } catch (error) {
      console.error("AI communication error:", error);
      setIsThinking(false);
    }
  };

  const toggleVoice = async () => {
    if (isVoiceEnabled) {
      stopSpeaking();
      setIsVoiceEnabled(false);
    } else {
      await initAudio();
      setIsVoiceEnabled(true);
    }
  };

  const toggleLive = () => {
    if (!isLiveMode) {
      const systemNotice: ChatMessage = {
        _id: 'sys_' + Date.now(),
        userId: 'corneila-id',
        message: "Switching to Live Human Architect protocol. Handing over controls...",
        timestamp: new Date()
      };
      setChatLog(prev => [...prev, systemNotice]);
    }
    setIsLiveMode(!isLiveMode);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60]">
      {!isOpen ? (
        <button
          onClick={() => setIsOpen(true)}
          className="bg-gradient-to-r from-neon-blue to-neon-purple p-4 rounded-full shadow-2xl hover:scale-110 transition-transform neon-glow-blue animate-bounce flex items-center justify-center group"
        >
          <MessageSquare className="text-white w-6 h-6" />
        </button>
      ) : (
        <div className="w-[320px] md:w-[400px] h-[600px] glassmorphism rounded-[2.5rem] flex flex-col overflow-hidden animate-slide-up shadow-2xl border border-white/10">
          {/* Header */}
          <div className="bg-gradient-to-r from-neon-blue/20 to-neon-purple/20 p-5 flex justify-between items-center border-b border-white/10 backdrop-blur-xl">
            <div className="flex items-center space-x-3">
              <div className="relative">
                <div className={`w-12 h-12 rounded-full bg-gradient-to-tr from-neon-blue to-neon-purple p-[2px] transition-all duration-500 ${isSpeaking ? 'scale-110 shadow-[0_0_20px_rgba(0,207,255,0.5)]' : ''}`}>
                  <div className="w-full h-full rounded-full overflow-hidden bg-dark-bg">
                    <img src={isLiveMode ? "https://picsum.photos/seed/human/200" : IMAGES.profile} className={`w-full h-full object-cover transition-all`} alt="Avatar" />
                  </div>
                </div>
                <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-dark-bg ${isLiveMode ? (socketConnected ? 'bg-green-500' : 'bg-red-500') : 'bg-neon-blue'}`} />
              </div>
              <div>
                <div className="flex items-center space-x-2">
                  <span className="font-heading text-[10px] tracking-widest uppercase block text-neon-blue">
                    {isLiveMode ? 'Live Interface' : 'Neural Node'}
                  </span>
                </div>
                <span className="text-sm font-heading tracking-tight text-white block">
                  {isLiveMode ? 'HUMAN ARCHITECT' : 'CORNEILA AI'}
                </span>
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={toggleLive}
                className={`p-2.5 rounded-xl transition-all ${isLiveMode ? 'bg-neon-purple text-white' : 'bg-white/5 text-gray-500 hover:text-white'}`}
                title={isLiveMode ? "Switch to AI" : "Talk to Human"}
              >
                <Radio size={18} className={isLiveMode ? 'animate-pulse' : ''} />
              </button>
              <button 
                onClick={toggleVoice} 
                className={`p-2.5 rounded-xl transition-all ${isVoiceEnabled ? 'bg-neon-blue text-dark-bg shadow-[0_0_20px_rgba(0,207,255,0.4)]' : 'bg-white/5 text-gray-500 hover:text-white'}`}
                title={isVoiceEnabled ? "Mute Voice" : "Enable Voice"}
              >
                {isVoiceEnabled ? <Volume2 size={18} /> : <VolumeX size={18} />}
              </button>
              <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-white p-2.5 hover:bg-white/5 rounded-xl transition-colors">
                <X size={20} />
              </button>
            </div>
          </div>

          {/* Chat Body */}
          <div ref={scrollRef} className="flex-grow overflow-y-auto p-5 space-y-6 font-body text-sm custom-scrollbar bg-black/10">
            {chatLog.map((chat) => (
              <div key={chat._id} className={`flex flex-col ${chat.userId === userId ? 'items-end' : 'items-start'}`}>
                <div className={`max-w-[85%] px-5 py-4 rounded-[1.8rem] shadow-lg transition-all ${
                  chat.userId === userId 
                    ? 'bg-gradient-to-br from-neon-blue to-neon-purple text-white rounded-tr-none border border-white/10'
                    : 'bg-white/5 text-gray-200 border border-white/10 rounded-tl-none backdrop-blur-md' 
                }`}>
                  <p>{chat.message}</p>
                  {chat.isLive && (
                    <div className="flex items-center space-x-1 mt-1 opacity-50 text-[8px] uppercase tracking-tighter">
