              />
              <button 
                onClick={handleSend} 
                disabled={isThinking || !message.trim() || (isLiveMode && !socketConnected)}
                className={`absolute right-2 p-3 rounded-xl transition-all shadow-lg ${isLiveMode ? 'bg-neon-purple' : 'bg-neon-blue'} text-white`}
              >
                <Send size={16} />
