              </div>
              <span className="font-heading text-lg font-bold tracking-widest bg-clip-text text-transparent bg-gradient-to-r from-neon-blue to-neon-purple hidden sm:block">
                CORNELIUS <span className="text-white">TEC</span>
              </span>
            </Link>
          </div>

          <div className="hidden md:flex items-center space-x-8">
