              <Radio size={10} className="text-neon-blue animate-pulse" />
              <span className="text-[8px] font-heading uppercase tracking-[0.2em] text-gray-400">Signal: Optimal</span>
            </div>

            {navLinks.map((link) => (
              <Link
                key={link.name}
                to={link.path}
                className={`px-2 py-1 text-[10px] font-heading uppercase tracking-widest transition-all duration-300 relative group ${
                  isActive(link.path)
                    ? 'text-neon-blue'
                    : 'text-gray-400 hover:text-white'
