import React, { useState } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Sparkles, Wand2, Download, RefreshCcw, Image as ImageIcon, Loader2, History, Terminal as TerminalIcon, Trash2, Cpu, FileText, Layout } from 'lucide-react';

interface VisionArchive {
  id: string;
  prompt: string;
  url?: string;
  blueprint?: string;
  type: 'visual' | 'blueprint';
  timestamp: Date;
}

export const DesignLab: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [mode, setMode] = useState<'visual' | 'blueprint'>('visual');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedContent, setGeneratedContent] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [archive, setArchive] = useState<VisionArchive[]>([]);
  const [logs, setLogs] = useState<string[]>(["Neural Forge initialized.", "Standby for transmission..."]);

  const addLog = (msg: string) => {
    setLogs(prev => [msg, ...prev].slice(0, 10));
  };

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setIsGenerating(true);
    setError(null);
    setGeneratedContent(null);
    addLog(`Initiating sequence in ${mode} mode...`);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (mode === 'visual') {
        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash-image',
          contents: {
            parts: [
              { text: `A futuristic, high-tech, professional brand asset or architectural concept in an Afro-futuristic style: ${prompt}. Cinematic lighting, 8k resolution, elegant textures.` }
            ]
          },
          config: {
            imageConfig: { aspectRatio: "16:9" }
          }
        });

        let foundImage = false;
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            setGeneratedContent(imageUrl);

            setArchive(prev => [{
              id: Date.now().toString(),
              prompt: prompt,
              url: imageUrl,
              type: 'visual',
              timestamp: new Date()
            }, ...prev]);
            addLog("Visual mapping complete.");
            foundImage = true;
            break;
          }
        }
        if (!foundImage) throw new Error("Neural link failed to provide visual data.");
      } else {
        // Blueprint Mode
        const response = await ai.models.generateContent({
          model: 'gemini-3-pro-preview',
          contents: `Create a professional technical blueprint or software architecture overview for the following concept: ${prompt}. Provide structure, recommended tech stack (prioritize futuristic options), and core logic steps. Format as clean Markdown. Use African tech metaphors where appropriate.`,
          config: {
            thinkingConfig: { thinkingBudget: 2000 }
          }
        });

        const blueprint = response.text || "Failed to draft blueprint.";
        setGeneratedContent(blueprint);
        setArchive(prev => [{
          id: Date.now().toString(),
          prompt: prompt,
          blueprint: blueprint,
          type: 'blueprint',
          timestamp: new Date()
        }, ...prev]);
        addLog("Architectural drafting complete.");
      }
    } catch (err: any) {
      setError("Neural link interrupted. Please recalibrate your prompt.");
      addLog("Critical Error: Sync failed.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="pt-24 pb-32 max-w-7xl mx-auto px-4">
      <div className="flex flex-col lg:flex-row gap-16 items-start">
        {/* Left Panel */}
        <div className="w-full lg:w-1/3 sticky top-32">
          <div className="inline-flex items-center space-x-2 mb-6 px-4 py-1 glassmorphism border border-neon-blue/30 rounded-full">
            <Sparkles size={14} className="text-neon-blue animate-pulse" />
            <span className="text-neon-blue font-heading text-[10px] tracking-[0.3em] uppercase">The Architect v3.0</span>
          </div>

          <h1 className="font-heading text-4xl md:text-5xl mb-6 tracking-tight">
            THE <span className="text-neon-purple text-shadow-purple">DESIGN</span> LAB
          </h1>

          <div className="glassmorphism p-8 rounded-[2.5rem] border border-white/5 shadow-2xl african-pattern mb-8">
            <div className="flex space-x-2 mb-6 p-1 bg-white/5 rounded-xl border border-white/5">
              <button 
                onClick={() => setMode('visual')}
                className={`flex-1 py-3 rounded-lg flex items-center justify-center space-x-2 transition-all ${mode === 'visual' ? 'bg-neon-blue text-dark-bg' : 'text-gray-500 hover:text-white'}`}
              >
                <ImageIcon size={14} />
                <span className="text-[10px] font-heading uppercase tracking-widest">Visual</span>
              </button>
              <button 
                onClick={() => setMode('blueprint')}
                className={`flex-1 py-3 rounded-lg flex items-center justify-center space-x-2 transition-all ${mode === 'blueprint' ? 'bg-neon-purple text-white' : 'text-gray-500 hover:text-white'}`}
              >
                <Cpu size={14} />
                <span className="text-[10px] font-heading uppercase tracking-widest">Blueprint</span>
              </button>
            </div>

            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder={mode === 'visual' ? "Visualize a floating data palace in Kigali..." : "Draft a blueprint for a blockchain logistics system in Liberia..."}
              className="w-full bg-black/40 border border-white/10 rounded-2xl p-6 text-sm font-body text-white focus:outline-none focus:border-neon-blue transition-all min-h-[140px] resize-none mb-6 shadow-inner"
            />

            <button
              onClick={handleGenerate}
              disabled={isGenerating || !prompt.trim()}
              className={`w-full font-heading py-5 rounded-2xl flex items-center justify-center space-x-3 hover:scale-[1.02] active:scale-95 transition-all shadow-2xl disabled:opacity-20 ${mode === 'visual' ? 'bg-neon-blue text-dark-bg' : 'bg-neon-purple text-white'}`}
            >
              {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <><Wand2 size={20} /><span>{mode === 'visual' ? 'INITIATE VISION' : 'DRAFT BLUEPRINT'}</span></>}
            </button>
          </div>

          <div className="glassmorphism p-6 rounded-[2rem] border border-white/5 bg-black/40 font-mono">
             <div className="flex items-center space-x-2 mb-4">
                <TerminalIcon size={12} className="text-neon-blue" />
                <span className="text-[9px] uppercase tracking-widest text-gray-500">Neural Log</span>
             </div>
             <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar">
                {logs.map((log, i) => (
                  <div key={i} className="text-[10px] text-gray-400">
                    <span className="text-neon-blue mr-2">&gt;</span>{log}
                  </div>
                ))}
             </div>
          </div>
        </div>

        {/* Output Area */}
        <div className="flex-grow w-full space-y-12">
          <div className="relative min-h-[500px] glassmorphism rounded-[3rem] border border-white/10 overflow-hidden group shadow-2xl bg-black/20">
            {isGenerating ? (
              <div className="absolute inset-0 flex flex-col items-center justify-center space-y-4">
                <div className="relative w-24 h-24">
                  <div className="absolute inset-0 border-4 border-neon-blue/20 rounded-full" />
                  <div className="absolute inset-0 border-4 border-t-neon-blue rounded-full animate-spin" />
                </div>
                <p className="font-heading text-[10px] text-neon-blue tracking-[0.5em] uppercase animate-pulse">Processing Signal</p>
              </div>
            ) : generatedContent ? (
              mode === 'visual' ? (
                <img src={generatedContent} alt="Neural Vision" className="w-full h-full object-cover animate-fade-in" />
              ) : (
                <div className="p-12 font-body text-gray-300 prose prose-invert max-w-none animate-fade-in">
                  <div className="flex items-center space-x-2 mb-8 border-b border-white/10 pb-4">
                    <FileText className="text-neon-purple" />
                    <span className="text-[10px] font-heading uppercase tracking-widest text-white">Digital Blueprint Manifest</span>
                  </div>
                  <div className="whitespace-pre-wrap leading-relaxed text-sm">
                    {generatedContent}
                  </div>
                </div>
              )
            ) : (
              <div className="absolute inset-0 flex flex-col items-center justify-center opacity-20">
                <Layout size={64} className="mb-4" />
                <p className="font-heading text-xs tracking-widest uppercase">Forge Standby</p>
              </div>
            )}

            {isGenerating && (
              <div className="absolute inset-0 pointer-events-none overflow-hidden">
                <div className="w-full h-1 bg-neon-blue/50 shadow-[0_0_20px_#00CFFF] absolute top-0 animate-[scan_2s_linear_infinite]" />
              </div>
            )}
          </div>

          <div>
             <div className="flex justify-between items-center mb-8">
                <div className="flex items-center space-x-3">
                   <History size={18} className="text-neon-purple" />
                   <h3 className="font-heading text-xl uppercase tracking-widest">Neural Archive</h3>
                </div>
                {archive.length > 0 && (
                   <button onClick={() => setArchive([])} className="text-gray-600 hover:text-red-400 transition-colors">
                      <Trash2 size={16} />
                   </button>
                )}
             </div>

             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {archive.map((entry) => (
                  <div 
                    key={entry.id} 
                    onClick={() => {
                      setMode(entry.type);
                      setGeneratedContent(entry.type === 'visual' ? entry.url! : entry.blueprint!);
                    }}
                    className="group relative aspect-video glassmorphism rounded-2xl overflow-hidden border border-white/5 cursor-pointer hover:border-neon-blue/30 transition-all p-2"
                  >
                     {entry.type === 'visual' ? (
                       <img src={entry.url} className="w-full h-full object-cover rounded-xl opacity-60 group-hover:opacity-100 transition-all" />
                     ) : (
                       <div className="w-full h-full flex flex-col items-center justify-center bg-neon-purple/5 rounded-xl">
                          <Cpu className="text-neon-purple/40 mb-2" />
                          <p className="text-[8px] font-heading uppercase tracking-widest text-gray-500">Blueprint Data</p>
                       </div>
                     )}
                     <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all p-4 flex flex-col justify-end">
                        <p className="text-[8px] text-white font-body truncate uppercase tracking-widest">{entry.prompt}</p>
                        <span className="text-neon-blue text-[7px] font-heading mt-1">RECALL NODE</span>
                     </div>
                  </div>
                ))}
             </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scan { 0% { top: -5%; } 100% { top: 105%; } }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0, 207, 255, 0.2); }
      `}</style>
    </div>
  );
};

