import React, { useState } from 'react';
import { Calendar as CalendarIcon, Send, User, Mail, Sparkles, Check } from 'lucide-react';
import { bookAppointment } from '../api';
import { SERVICES } from '../constants';

export default function AppointmentForm() {
  const [form, setForm] = useState({ name: "", email: "", date: "", service: SERVICES[0].id });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isComplete, setIsComplete] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await bookAppointment(form);
      setIsComplete(true);
    } catch (err) {
      // Fallback for demo
      setTimeout(() => setIsComplete(true), 1500);
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isComplete) {
    return (
      <div className="glassmorphism p-12 rounded-[3rem] border border-neon-blue/20 text-center animate-fade-in shadow-2xl">
        <div className="w-20 h-20 bg-neon-blue rounded-full flex items-center justify-center mx-auto mb-8 shadow-[0_0_30px_rgba(0,207,255,0.4)]">
          <Check size={40} className="text-dark-bg" />
        </div>
        <h2 className="font-heading text-3xl text-white mb-4">Transmission Received</h2>
        <p className="text-gray-400 font-subheading mb-8">An architect from the Cornelius Matrix will contact you shortly to sync requirements.</p>
        <button 
          onClick={() => setIsComplete(false)}
          className="text-neon-blue font-heading text-[10px] tracking-widest uppercase hover:text-white transition-colors"
        >
          Book Another Session
        </button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="glassmorphism p-10 md:p-14 rounded-[3.5rem] border border-white/5 shadow-2xl african-pattern relative overflow-hidden space-y-8">
      <div className="mb-4">
        <div className="inline-flex items-center space-x-2 mb-6 px-3 py-1 bg-white/5 border border-white/10 rounded-full">
          <Sparkles size={12} className="text-neon-blue" />
          <span className="text-[9px] font-heading text-neon-blue uppercase tracking-widest">Strategy Portal</span>
        </div>
        <h3 className="font-heading text-3xl text-white">Initiate <span className="text-neon-purple">Discovery</span></h3>
      </div>

      <div className="space-y-6">
        <div className="relative group">
          <User className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-500 group-focus-within:text-neon-blue transition-colors" size={18} />
          <input 
            required
            type="text" 
            placeholder="Identity / Name" 
            className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-5 focus:outline-none focus:border-neon-blue transition-all text-white font-subheading"
            onChange={(e) => setForm({ ...form, name: e.target.value })} 
          />
        </div>

        <div className="relative group">
          <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-500 group-focus-within:text-neon-purple transition-colors" size={18} />
          <input 
            required
            type="email" 
            placeholder="Neural Signal (Email)" 
            className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-5 focus:outline-none focus:border-neon-purple transition-all text-white font-subheading"
            onChange={(e) => setForm({ ...form, email: e.target.value })} 
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="relative group">
            <CalendarIcon className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-500 group-focus-within:text-neon-blue transition-colors" size={18} />
            <input 
              required
              type="date" 
              className="w-full bg-black/40 border border-white/10 rounded-2xl pl-14 pr-6 py-5 focus:outline-none focus:border-neon-blue transition-all text-white font-subheading appearance-none color-scheme-dark"
              onChange={(e) => setForm({ ...form, date: e.target.value })} 
            />
          </div>

          <select 
            className="w-full bg-black/40 border border-white/10 rounded-2xl px-6 py-5 focus:outline-none focus:border-neon-purple transition-all text-white font-subheading appearance-none"
            onChange={(e) => setForm({ ...form, service: e.target.value })}
            value={form.service}
          >
            {SERVICES.map(s => (
              <option key={s.id} value={s.id}>{s.title}</option>
            ))}
          </select>
        </div>
      </div>

      <button 
        type="submit" 
        disabled={isSubmitting}
        className="w-full bg-white text-dark-bg font-heading py-6 rounded-2xl hover:scale-[1.02] active:scale-95 transition-all shadow-2xl flex items-center justify-center space-x-3 group disabled:opacity-50"
      >
        {isSubmitting ? (
          <div className="w-6 h-6 border-2 border-dark-bg border-t-transparent rounded-full animate-spin" />
        ) : (
          <>
            <span className="text-xs tracking-[0.3em] uppercase font-bold">Transmit Request</span>
            <Send size={18} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
          </>
        )}
      </button>

      <div className="pt-4 text-center">
        <p className="text-[9px] text-gray-600 font-accent uppercase tracking-[0.4em]">All sessions are subject to neural bandwidth availability.</p>
      </div>
    </form>
  );
}

