import React, { useEffect, useState } from "react";
import { getProducts } from "../api";

export default function Marketplace() {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    async function fetchData() {
      const res = await getProducts();
      setProducts(res.data);
    }
    fetchData();
  }, []);

  return (
    <section id="marketplace" className="bg-gray-900 text-white py-16">
      <h2 className="text-3xl font-bold text-center mb-8">Marketplace</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 px-8">
        {products.map((p) => (
          <div key={p._id} className="p-6 border border-purple-500 rounded-lg">
            <h3 className="text-xl font-bold">{p.title}</h3>
            <p>{p.description}</p>
            <p className="mt-2 text-blue-400">${p.price}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

