import React, { useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

export default function ChatWidget() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");

  socket.on("chatMessage", (msg) => {
    setMessages((prev) => [...prev, msg]);
  });

  const sendMessage = () => {
    socket.emit("chatMessage", { userId: "123", message: input });
    setInput("");
  };

  return (
    <div className="fixed bottom-4 right-4 bg-gray-800 text-white p-4 rounded-lg w-64">
      <h3 className="font-bold mb-2">Live Chat</h3>
      <div className="h-32 overflow-y-auto mb-2">
        {messages.map((m, i) => <p key={i}>{m.message}</p>)}
      </div>
      <input 
        value={input} 
        onChange={(e) => setInput(e.target.value)} 
        className="w-full p-2 text-black rounded mb-2"
      />
      <button onClick={sendMessage} className="bg-blue-500 px-4 py-2 rounded">Send</button>
    </div>
  );
}

